 .../controllers/screenbrightnesscontroller.h  |  7 ++++
 daemon/powerdevilbrightnesslogic.cpp          |  7 ++++
 daemon/powerdevilbrightnesslogic.h            |  5 +++
 daemon/powerdevilcore.cpp                     |  1 +
 daemon/powerdevilscreenbrightnesslogic.cpp    | 23 ++++++++++-
 daemon/powerdevilscreenbrightnesslogic.h      | 11 ++++++
 kcm/ui/GlobalConfig.qml                       | 39 ++++++++++++++++++-
 9 files changed, 104 insertions(+), 3 deletions(-)

