diff --git a/daemon/powerdevilscreenbrightnesslogic.cpp b/daemon/powerdevilscreenbrightnesslogic.cpp
index 18943a8fc..0a598e9fe 100644
--- a/daemon/powerdevilscreenbrightnesslogic.cpp
+++ b/daemon/powerdevilscreenbrightnesslogic.cpp
@@ -8,19 +8,38 @@
 #include "powerdevil_debug.h"
 #include <QDebug>

+#include <algorithm>
+#include <cmath>
+
 namespace PowerDevil
 {

+void ScreenBrightnessLogic::setStepPercent(int stepPercent)
+{
+    stepPercent = std::clamp(stepPercent, 1, 100);
+    if (stepPercent != m_stepPercent) {
+        m_stepPercent = stepPercent;
+        updateSteps();
+    }
+}
+
 int ScreenBrightnessLogic::calculateSteps(int maxValue) const
 {
-    // We assume that the preferred number of steps for screen brightness is 20, but we don't want more.
+    // The preferred number of steps for screen brightness follows the configured step size
+    // (20 for the default 5%), but we don't want more.
+    const int preferredSteps = std::round(100.0 / m_stepPercent);

-    if (maxValue <= 20) {
+    if (maxValue <= preferredSteps) {
         // Too few steps, return the number of actual steps.
         // Those would be uniform, but not round in some cases.
         return maxValue;
     }

+    if (preferredSteps != 20) {
+        // The rest is tuned for 20 steps, use other step sizes as they are.
+        return preferredSteps;
+    }
+
     if (maxValue >= 100 || maxValue % 20 == 0 || (maxValue >= 80 && maxValue % 4 == 0)) {
         // In this case all 20 steps are perfect.
         return 20;
diff --git a/daemon/powerdevilscreenbrightnesslogic.h b/daemon/powerdevilscreenbrightnesslogic.h
index f64c05c51..5f0a5fdbd 100644
--- a/daemon/powerdevilscreenbrightnesslogic.h
+++ b/daemon/powerdevilscreenbrightnesslogic.h
@@ -12,7 +12,18 @@ namespace PowerDevil
 {
 class ScreenBrightnessLogic : public BrightnessLogic
 {
+public:
+    /**
+     * Sets the preferred size of a regular brightness step, in percent.
+     *
+     * @param stepPercent Step size, from 1 to 100
+     */
+    void setStepPercent(int stepPercent);
+
 protected:
     int calculateSteps(int valueMax) const override;
+
+private:
+    int m_stepPercent = 5;
 };
 }
