     )

     Kirigami.FormLayout {
@@ -396,6 +397,42 @@ Kirigami.ScrollablePage {
             visible: batteryLevelsHeader.visible || chargeLimitHeader.visible
         }

+        RowLayout {
+            Kirigami.FormData.label: i18nc("@label:spinbox", "&Brightness change step:")
+            Kirigami.FormData.buddyFor: brightnessStepSpin
+            spacing: Kirigami.Units.smallSpacing
+
+            QQC2.SpinBox {
+                id: brightnessStepSpin
+                Accessible.name: i18nc("@accessible:name:spinbox", "Brightness change step")
+                Accessible.description: brightnessStepContextualHelp.toolTipText
+                Layout.preferredWidth: root.maxImplicitWidthOfSpinBoxes
+                from: 1
+                to: 20
+
+                KCM.SettingStateBinding {
+                    configObject: root.globalSettings
+                    settingName: "BrightnessStep"
+                }
+                value: root.globalSettings.brightnessStep
+                onValueModified: {
+                    root.globalSettings.brightnessStep = value;
+                    // In Qt 6.6, SpinBox breaks the value binding on keyboard input. Restore it again.
+                    value = Qt.binding(() => root.globalSettings.brightnessStep);
+                }
+
+                editable: true
+                validator: percentageValidator
+                textFromValue: root.formatPercent
+                valueFromText: root.extractPercent
+            }
+
+            Kirigami.ContextualHelpButton {
+                id: brightnessStepContextualHelp
+                toolTipText: i18nc("@info:whatsthis", "Screen brightness changes by this amount when pressing brightness keys or scrolling over the Brightness and Color widget.")
+            }
+        }
+
         QQC2.CheckBox {
             Kirigami.FormData.label: i18nc("@label:checkbox", "&Media playback:")
             text: i18nc("@text:checkbox", "Pause media players when suspending")
